package app.veyra;
import android.content.*;import org.json.*;import java.util.*;
final class PersonalStore {
 static SharedPreferences prefs(Context c){return ProfileStore.prefs(c,"personal");}
 static boolean hidden(Context c,JSONObject title){for(String key:editionKeys(title))if(prefs(c).getBoolean("hidden:"+key,false))return true;return false;}
 static void hide(Context c,JSONObject title,boolean hide){SharedPreferences.Editor edit=prefs(c).edit();for(String key:editionKeys(title))edit.putBoolean("hidden:"+key,hide);edit.apply();}
 private static Set<String> editionKeys(JSONObject title){Set<String> keys=new LinkedHashSet<>();keys.add(LibraryStore.key(title));JSONArray editions=title.optJSONArray("_editions");if(editions!=null)for(int i=0;i<Math.min(20,editions.length());i++){JSONObject e=editions.optJSONObject(i);if(e!=null&&(e.optString("provider").equals("current")||e.optString("provider").equals("classic"))&&!e.optString("id").isEmpty())keys.add(e.optString("provider")+":"+title.optString("_kind","movie")+":"+e.optString("id"));}return keys;}
 static void watched(Context c,JSONObject title,boolean watched){prefs(c).edit().putBoolean("watched:"+LibraryStore.key(title),watched).apply();ProfileStore.prefs(c,"watch-history").edit().remove(LibraryStore.key(title)).apply();SharedPreferences.Editor progress=ProfileStore.prefs(c,"resume").edit();for(String key:ProfileStore.prefs(c,"resume").getAll().keySet())if(key.startsWith(LibraryStore.key(title)+":"))progress.remove(key);progress.apply();}
 static void review(Context c,JSONObject title,int rating,String note){if(rating<0||rating>10||note.length()>500)throw new IllegalArgumentException();try{prefs(c).edit().putString("review:"+LibraryStore.key(title),new JSONObject().put("rating",rating).put("note",note).toString()).apply();}catch(JSONException ignored){}}
 static LinkedHashMap<String,JSONObject> collections(Context c){LinkedHashMap<String,JSONObject> out=new LinkedHashMap<>();List<String> keys=new ArrayList<>(prefs(c).getAll().keySet());Collections.sort(keys);for(String key:keys)if(key.startsWith("collection:"))try{out.put(key,new JSONObject(prefs(c).getString(key,"{}")));}catch(Exception ignored){}return out;}
 static String create(Context c,String name)throws Exception{if(name.trim().isEmpty()||name.length()>40||collections(c).size()>=20)throw new IllegalArgumentException("Use 1–40 characters and up to 20 collections");String id="collection:"+UUID.randomUUID();prefs(c).edit().putString(id,new JSONObject().put("name",name.trim()).put("titles",new JSONArray()).toString()).apply();return id;}
 static void add(Context c,String collection,JSONObject title)throws Exception{JSONObject group=collections(c).get(collection);if(group==null)throw new IllegalArgumentException();JSONArray titles=group.getJSONArray("titles");for(int i=0;i<titles.length();i++)if(LibraryStore.key(titles.getJSONObject(i)).equals(LibraryStore.key(title)))return;if(titles.length()>=1000)throw new IllegalArgumentException("Collection full");titles.put(VelixioData.cleanRecord(title,false));prefs(c).edit().putString(collection,group.toString()).apply();}
 static void remove(Context c,String collection,int index)throws Exception{JSONObject group=collections(c).get(collection);if(group==null)return;group.getJSONArray("titles").remove(index);prefs(c).edit().putString(collection,group.toString()).apply();}
 static JSONObject export(Context c)throws Exception{JSONObject raw=new JSONObject();for(Map.Entry<String,?> e:prefs(c).getAll().entrySet())raw.put(e.getKey(),e.getValue());return validate(raw);}
 static JSONObject validate(JSONObject raw)throws Exception{if(raw.length()>3000)throw new Exception("Too many personal records");JSONObject safe=new JSONObject();Iterator<String> keys=raw.keys();int groups=0,follows=0;while(keys.hasNext()){String key=keys.next();if(key.length()>300)throw new Exception("Invalid personal identity");if(key.equals("stat:watchMs")){Object value=raw.get(key);if(!(value instanceof Number)||!Double.isFinite(((Number)value).doubleValue())||((Number)value).doubleValue()!=((Number)value).longValue()||((Number)value).longValue()<0||((Number)value).longValue()>3600000000000L)throw new Exception("Invalid watch time");safe.put(key,((Number)value).longValue());}else if(key.startsWith("collection:")){if(++groups>20||!key.substring(11).matches("[a-f0-9-]{36}"))throw new Exception("Invalid collection");JSONObject group=new JSONObject(raw.getString(key));String name=group.getString("name");JSONArray titles=group.getJSONArray("titles"),clean=new JSONArray();if(name.trim().isEmpty()||name.length()>40||titles.length()>1000)throw new Exception("Invalid collection");for(int i=0;i<titles.length();i++)clean.put(VelixioData.cleanRecord(titles.getJSONObject(i),false));safe.put(key,new JSONObject().put("name",name).put("titles",clean).toString());}else if(key.matches("follow:(?:current|classic):(?:movie|short):[^/?]{1,256}")){if(++follows>20)throw new Exception("Too many followed series");JSONObject follow=FollowStore.validate(new JSONObject(raw.getString(key)));if(!key.equals(FollowStore.key(follow.getString("_provider"),follow.getString("_kind"),follow.getString("id"))))throw new Exception("Follow identity mismatch");safe.put(key,follow.toString());}else if(key.matches("(?:hidden|watched):(?:current|classic):(?:movie|short):[^/?]{1,256}")){if(!(raw.get(key) instanceof Boolean))throw new Exception("Invalid personal flag");safe.put(key,raw.getBoolean(key));}else if(key.matches("review:(?:current|classic):(?:movie|short):[^/?]{1,256}")){JSONObject review=new JSONObject(raw.getString(key));int rating=review.getInt("rating");String note=review.getString("note");if(rating<0||rating>10||note.length()>500)throw new Exception("Invalid review");safe.put(key,new JSONObject().put("rating",rating).put("note",note).toString());}else throw new Exception("Unknown personal field");}return safe;}
 static void restore(Context c,JSONObject safe)throws Exception{SharedPreferences.Editor edit=prefs(c).edit();Iterator<String> keys=safe.keys();while(keys.hasNext()){String key=keys.next();Object value=safe.get(key);if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Number)edit.putLong(key,((Number)value).longValue());else edit.putString(key,(String)value);}edit.apply();}
}
